import {occupations,occupationById,directoryOccupations,workActivityOptions,settingOptions} from './occupation-data.js?v=0.31.0';
import {careerDetail} from './finance-ui.js?v=0.31.0';
import {directions} from './content.js?v=0.31.0';
import {escapeHTML as h} from './model.js?v=0.31.0';
const zone=z=>z==null?'Preparation group not available':z<=2?'Job Zone 1–2':`Job Zone ${z}`;
const pctRows=a=>a?.length?a.map(x=>`${x.label} (${x.percent}%, n=${x.sampleSize??'not reported'}, ${x.referenceDate||'date unavailable'})`).join('; '):'Not available in the reviewed source';
const contextSummary=o=>o.context.items?.length?o.context.items.map(x=>`${x.name} (n=${x.sampleSize??'not reported'}, ${x.referenceDate||'date unavailable'}${x.suppressedCategoryCount?`; partial, O*NET marks ${x.suppressedCategoryCount} categories Recommend Suppress`:''}): ${x.responses.map(v=>`${v.label} (${v.percent}%)`).join(', ')}`).join('; '):'Not available in the reviewed source';
const sourceLink=s=>`<a class="comparison-source" href="${h(s.url)}" target="_blank" rel="noopener">${h(s.release)} · ${h(s.referencePeriod||s.referenceDate||'source date unavailable')} ↗</a>`;
function compareSources(o,label){const match=label==='Representative tasks'?['tasks']:label==='Work setting and demands'?['work context and settings']:label==='Preparation group'?['education, experience, training and Job Zone']:label==='Education reported by workers'?['education, experience, training and Job Zone']:label==='Experience and training'?['education, experience, training and Job Zone']:label==='Legal requirements'?['requirements']:label==='Related study'?['educationRoutes']:label.startsWith('Wages')?['earnings']:[];return (o.sources||[]).filter(s=>match.includes(s.field)||match.some(m=>s.field.startsWith(m))).map(sourceLink).join(' '); }
const selected=state=>state.exploration?.compareCareers||state.compareCareers||state.exploration?.savedCareers||state.exploration?.careerChoices||[];
const saved=state=>state.exploration?.savedCareers||state.savedCareers||state.exploration?.careerChoices||[];
const details=(label,values)=>values?.length?`<details class="occupation-disclosure"><summary>${h(label)} (${values.length})</summary><ul>${values.map(x=>`<li>${h(x)}</li>`).join('')}</ul></details>`:'';
function matchReason(o,q){if(!q)return 'Reviewed Fieldguide profile';const l=q.toLowerCase();if(o.title.toLowerCase().includes(l))return `Title contains “${q}”`;const a=o.aliases.find(x=>x.toLowerCase().includes(l));if(a)return `Also called “${a}”`;if(o.searchTerms?.some(x=>x.toLowerCase().includes(l)))return `Curated search match for “${q}”`;const t=o.tasks.find(x=>x.text.toLowerCase().includes(l));return t?`Task match: “${t.text}”`:'Matches occupational description';}
function matching(o,v){const q=(v.search||'').trim().toLowerCase();return (!q||[o.title,o.soc,...o.aliases,...(o.searchTerms||[]),o.summary,...o.tasks.map(t=>t.text)].join(' ').toLowerCase().includes(q))&&(!v.activity||o.activityTags.includes(v.activity))&&(!v.setting||o.settings.includes(v.setting))&&(!v.path||o.pathIds.includes(v.path))&&(!v.level||(String(v.level)==='1'?[1,2].includes(o.jobZone):String(o.jobZone)===String(v.level)));}
const card=(o,q)=>`<article class="occupation-card"><span class="overline">FIELDGUIDE REVIEWED · ${h(o.soc)}</span><h3><a href="#/career/${h(o.id)}">${h(o.title)}</a></h3><p>${h(o.summary||'A reviewed task summary is not available. See the official profile for current details.')}</p><p class="occupation-match">${h(matchReason(o,q))}</p><div class="tags">${o.activityTags.map(t=>`<span class="tag">${h(workActivityOptions.find(x=>x.id===t)?.label||t)}</span>`).join('')}</div><a class="text-link" href="#/career/${h(o.id)}">Explore tasks, preparation & sources →</a></article>`;
const externalCard=o=>`<article class="occupation-card external-occupation"><span class="overline">OFFICIAL EXTERNAL PROFILE · ${h(o.soc)}</span><h3><a href="${h(o.sourceURL)}" target="_blank" rel="noopener">${h(o.title)} ↗</a></h3><p>Fieldguide has not reviewed local education, cost, licensing, or work-setting details for this occupation.</p><a class="text-link" href="${h(o.sourceURL)}" target="_blank" rel="noopener">Open official profile →</a></article>`;
export function occupationCatalogPage(view={},state){const q=(view.search||'').trim(),external=view.coverage==='directory',reviewedBySoc=new Map(occupations.map(o=>[o.soc,o]));let list=external?directoryOccupations.filter(o=>(!q||`${o.title} ${o.soc}`.toLowerCase().includes(q.toLowerCase()))&&(!view.level||(String(view.level)==='1'?[1,2].includes(o.jobZone):String(o.jobZone)===String(view.level)))):occupations.filter(o=>matching(o,view));const active=(external?['level']:['activity','setting','level','path']).filter(k=>view[k]).map(k=>({activity:'Activity: '+(workActivityOptions.find(x=>x.id===view.activity)?.label||''),setting:'Setting: '+(settingOptions.find(x=>x.id===view.setting)?.label||''),level:'Preparation: '+(view.level==='1'?'Job Zone 1–2':`Job Zone ${view.level}`),path:'Pathway: '+view.path}[k]));const cards=list.map(o=>{const reviewed=external&&reviewedBySoc.get(o.soc);return reviewed?card(reviewed,q):external?externalCard(o):card(o,q)}).join('');return `<div class="page-intro catalog-intro"><div><span class="eyebrow">OCCUPATIONS · EXPLORE THE WORK</span><h1>Start with what people do.</h1><p class="intro-copy">Search titles, alternate names and real task language. Reviewed Fieldguide profiles are separate from official directory links.</p></div><button class="button secondary" data-action="catalog-type" data-id="majors">Fields of study ↗</button></div><section class="occupation-filters"><div class="occupation-filter-grid"><div class="field"><label for="catalog-search" class="label">Search a title, alternate name or task</label><input id="catalog-search" type="search" placeholder="Try “help people with mental health”…" value="${h(q)}"></div><div class="field"><label for="catalog-activity" class="label">Work activity (browsing tags)</label><select id="catalog-activity" data-catalog="activity" ${external?'disabled':''}><option value="">Any activity</option>${workActivityOptions.map(x=>`<option value="${h(x.id)}" ${view.activity===x.id?'selected':''}>${h(x.label)}</option>`).join('')}</select>${external?'<small>Activity tags are available on reviewed profiles only.</small>':''}</div><div class="field"><label for="catalog-path" class="label">Broad pathway</label><select id="catalog-path" data-catalog="path" ${external?'disabled':''}><option value="">Any pathway</option>${[...new Set(occupations.flatMap(o=>o.pathIds))].map(id=>`<option value="${h(id)}" ${view.path===id?'selected':''}>${h(directions.find(d=>d.id===id)?.title||id)}</option>`).join('')}</select>${external?'<small>Pathway tags are available on reviewed profiles only.</small>':''}</div><div class="field"><label for="catalog-zone" class="label">Preparation group</label><select id="catalog-zone" data-catalog="level"><option value="">Any Job Zone</option>${[['1–2',1],['3',3],['4',4],['5',5]].map(([label,id])=>`<option value="${id}" ${String(view.level)===String(id)?'selected':''}>Job Zone ${label}</option>`).join('')}</select></div>${settingOptions.length?`<div class="field"><label for="catalog-setting" class="label">Work setting</label><select id="catalog-setting" data-catalog="setting" ${external?'disabled':''}><option value="">Any documented setting</option>${settingOptions.map(x=>`<option value="${h(x.id)}" ${view.setting===x.id?'selected':''}>${h(x.label)}</option>`).join('')}</select>${external?'<small>Setting tags are available on reviewed profiles only.</small>':''}</div>`:''}</div><div class="occupation-filter-meta"><div class="occupation-coverage"><button data-action="occupation-coverage" data-id="reviewed" aria-pressed="${!external}">Fieldguide reviewed (${occupations.length})</button><button data-action="occupation-coverage" data-id="directory" aria-pressed="${external}">Official directory (${directoryOccupations.length} total)</button></div><span>${list.length} ${external?'directory entries':'reviewed careers'}</span><button data-action="occupation-clear" class="text-link">Reset filters</button></div>${active.length?`<div class="occupation-filter-chips" aria-label="Active filters">${active.map(x=>`<span class="tag">${h(x)}</span>`).join('')}</div>`:''}</section><div class="section-title"><h2>${list.length} ${external?'official directory entries':'reviewed profiles'}</h2><span>Match reasons are shown on results.</span></div><div class="occupation-grid">${cards||`<div class="empty-state"><h3>No occupations match those filters.</h3><p>Try a broader task phrase, remove a filter, or browse the official directory.</p><button class="button secondary" data-action="occupation-clear">Reset filters</button> <button class="button secondary" data-action="occupation-coverage" data-id="directory">Browse official directory</button></div>`}</div><p class="occupation-attribution">O*NET 31.0 / My Next Move occupational content. Directory records marked external have no reviewed local Fieldguide detail.</p>`;}
export function occupationPage(id,state={}){const o=occupationById(id);if(!o){const ext=directoryOccupations.find(x=>x.id===id);return ext?`<div class="page-intro catalog-intro"><div><span class="eyebrow">OFFICIAL EXTERNAL PROFILE</span><h1>${h(ext.title)}</h1><p class="intro-copy">Fieldguide has not reviewed a local profile for this occupation.</p></div><a class="button secondary" href="${h(ext.sourceURL)}" target="_blank" rel="noopener">Open official profile ↗</a></div><div class="context-panel"><p>Local education, legal requirements, costs, wages, and work context are not available in a reviewed Fieldguide record.</p><a href="${h(ext.sourceURL)}" target="_blank" rel="noopener">My Next Move · ${h(ext.soc)}</a></div>`:'<h1>Career not found.</h1><a href="#/catalog">Browse occupations</a>';}
const isSaved=saved(state).includes?.(o.id)||false,isCompared=(state.exploration?.compareCareers||state.compareCareers||[]).includes?.(o.id)||false, finance=o.finance?careerDetail(id,state,{embedded:true}):'', tasks=o.tasks.length?o.tasks.map(t=>`<li>${h(t.text)} <a href="${h(t.source)}" target="_blank" rel="noopener">Source ↗</a></li>`).join(''):'<li>Task summary unavailable in this reviewed record.</li>',related=o.relatedIds.map(occupationById).filter(Boolean),suppressedSettings=Object.entries(o.settingEvidence.status||{}).filter(([,v])=>v==='not_derived_recommended_suppression').map(([k])=>k==='indoors'?'indoor':'outdoor');return `<div class="page-intro occupation-intro"><div><span class="eyebrow">FIELDGUIDE REVIEWED · ${h(o.soc)}</span><h1>${h(o.title)}</h1><p class="intro-copy">${h(o.summary||'Summary unavailable in this source snapshot.')}</p><div class="occupation-actions"><button class="button secondary" data-action="career-save" data-id="${h(o.id)}" aria-pressed="${isSaved}">${isSaved?'Saved':'Save career'}</button><button class="button secondary" data-action="career-compare" data-id="${h(o.id)}" aria-pressed="${isCompared}">${isCompared?'In comparison':'Add to compare'}</button><button class="button" data-action="career-experiment" data-id="${h(o.id)}">Plan an experiment</button></div></div><a class="text-link" href="#/catalog">← Browse occupations</a></div><section class="context-panel"><span class="overline">WHAT YOU WOULD DO</span><h2>Representative tasks</h2><ul class="occupation-tasks">${tasks}</ul>${o.aliases.length?`<p><strong>Also called:</strong> ${o.aliases.map(h).join(' · ')}</p>`:''}</section><section class="context-panel"><span class="overline">WHAT THE WORK CAN FEEL LIKE</span><h2>Context to investigate</h2><p>${o.settings.length?`Reported setting exposure: ${o.settings.map(x=>x==='indoors'?'Indoor exposure reported':'Outdoor exposure reported').join(' · ')}`:`No indoor/outdoor browse tag is asserted from available work-context responses.${Object.values(o.settingEvidence.status||{}).includes('not_derived_recommended_suppression')?' One or more categories are marked Recommend Suppress, so the affected exposure was not inferred.':''}`}</p>${suppressedSettings.length?`<p class="source-note">${h(suppressedSettings.join(' and '))} setting exposure was not inferred because at least one related O*NET category is marked Recommend Suppress.</p>`:''}<p>${h(o.context.reason||'Work conditions are not available in this profile.')}</p>${o.context.items?.length?`<div class="work-context-grid">${o.context.items.map(x=>`<article><strong>${h(x.name)}</strong><p>${x.responses.map(v=>`${h(v.label)} · ${h(v.percent)}%`).join('<br>')}</p><small>Available O*NET incumbent response categories · n=${h(x.sampleSize??x.responses[0]?.sampleSize??'not reported')} · ${h(x.referenceDate||'date unavailable')}${x.suppressedCategoryCount?` · ${x.suppressedCategoryCount} other categories are marked Recommend Suppress; these displayed shares are partial, not a complete or ranked distribution`:''}</small></article>`).join('')}</div><p class="source-note">Indoor/outdoor browse tags use this editorial rule: ${h(o.settingEvidence.rule)} Categories marked Recommend Suppress are withheld from display; visible shares for those items are partial and must not be read as a complete or ranked distribution.</p>`:''}</section><section class="context-panel"><span class="overline">WAYS TO PREPARE</span><h2>${h(zone(o.jobZone))}</h2><p>Job Zones group typical occupational preparation using education, experience, and training. This classification is not a student ability level or legal rule.</p>${o.preparation.educationDistribution?.length?`<h3>Education reported by workers</h3><ul>${o.preparation.educationDistribution.map(x=>`<li>${h(x.label)} · ${h(x.percent)}% of responses · n=${h(x.sampleSize??'not reported')} (${h(x.referenceDate||'date unavailable')})</li>`).join('')}</ul><p class="source-note">Surveyed worker education is descriptive and is not an entry requirement or a licensing rule.</p>`:'<p>Worker education distribution is not available in this source.</p>'}${['Related Work Experience','On-the-Job Training','On-Site or In-Plant Training'].map((name,i)=>{const a=[o.preparation.relatedExperience,o.preparation.onTheJobTraining,o.preparation.onSiteTraining][i];return a?.length?`<h3>${h(name)} reported in the occupation</h3><ul>${a.map(x=>`<li>${h(x.label)} · ${h(x.percent)}% of responses · n=${h(x.sampleSize??'not reported')} (${h(x.referenceDate||'date unavailable')})</li>`).join('')}</ul>`:`<p>${h(name)}: unavailable in this source.</p>`}).join('')}<p>Job Zone source: <a href="${h(o.preparation.sourceURL)}" target="_blank" rel="noopener">O*NET OnLine occupation profile</a>; Job Zone data date ${h(o.preparation.jobZoneReferenceDate||'unavailable')}. O*NET profile information checked ${h(o.preparation.checkedAt)}.</p>${details('Knowledge',o.knowledge)}${details('Skills',o.skills)}${details('Abilities',o.abilities)}${details('Work styles',o.workStyles)}</section><section class="context-panel"><span class="overline">TRY AND COMPARE</span><h2>${h(o.experiment.title)}</h2><p>${h(o.experiment.detail)}</p><p>${h(o.experiment.notice)}</p><button class="button secondary" data-action="career-experiment" data-id="${h(o.id)}">Add experiment to my plan</button> <a class="text-link" href="#/career-reflection/${h(o.id)}">Reflect on this career ↗</a>${related.length?`<h3>Related occupations</h3><div class="related-careers">${related.map(r=>`<a class="requirement-mini" href="#/career/${h(r.id)}"><strong>${h(r.title)}</strong><span>Explore this distinct role →</span></a>`).join('')}</div>`:''}</section><details class="context-panel source-disclosure"><summary>Sources, release dates and attribution</summary><ul>${o.sources.map(s=>`<li><a href="${h(s.url)}" target="_blank" rel="noopener">${h(s.publisher)} · ${h(s.field)}</a> — ${h(s.release)}; reference ${h(s.referencePeriod||s.referenceDate||'not provided')}; checked ${h(s.checkedAt)}. ${h(s.license||'')}${s.downloadURL?` <a href="${h(s.downloadURL)}" target="_blank" rel="noopener">Source data file ↗</a>`:''}${s.licenseURL?` <a href="${h(s.licenseURL)}" target="_blank" rel="noopener">License ↗</a>`:''}</li>`).join('')}</ul><p>Includes My Next Move occupational information, developed by the National Center for O*NET Development. O*NET is a registered trademark of USDOL/ETA. O*NET 31.0 database facts are attributed to USDOL/ETA under CC BY 4.0. We selected three high-importance task statements, retained available context categories, withheld categories marked Recommend Suppress, and derived indoor/outdoor browse tags using the displayed 40% threshold. A partial distribution is not a complete or ranked distribution. Missing rows mean that a current sourced distribution was unavailable; they do not imply zero exposure or preparation.</p></details>${finance||`<section class="context-panel"><span class="overline">PAY, OUTLOOK AND AFFORDABILITY</span><h2>Local facts have not been reviewed</h2><p>Fieldguide has no linked local wage, outlook, education-cost, or legal-requirement record for this occupation. Check official sources for the location and role you want to investigate.</p></section>`}`;}
export function careerComparisonPage(state={}){const ids=[...new Set(selected(state))].slice(0,3),items=ids.map(occupationById).filter(Boolean);if(!items.length)return `<div class="page-intro catalog-intro"><div><span class="eyebrow">COMPARE OCCUPATIONS</span><h1>Compare the work itself.</h1><p class="intro-copy">Save up to three careers from reviewed profiles.</p></div><a class="button" href="#/catalog">Browse occupations ↗</a></div><div class="empty-state"><h2>No careers selected yet.</h2><p>Open a reviewed profile and choose “Add to compare.”</p></div>`;const rows=[['Representative tasks',o=>o.tasks.map(t=>t.text).join('; ')||'Not available'],['Work setting and demands',o=>`${o.settings.map(x=>x==='indoors'?'Indoor exposure reported':'Outdoor exposure reported').join('; ')||'No setting tags available'} — ${contextSummary(o)}`],['Preparation group',o=>o.jobZone?zone(o.jobZone):'Not available'],['Education reported by workers',o=>pctRows(o.preparation.educationDistribution)],['Experience and training',o=>['Related Work Experience','On-the-Job Training','On-Site or In-Plant Training'].map((name,i)=>`${name}: ${pctRows([o.preparation.relatedExperience,o.preparation.onTheJobTraining,o.preparation.onSiteTraining][i])}`).join(' · ')],['Legal requirements',o=>o.finance?.requirements?.license||'Not reviewed for this role and jurisdiction'],['Related study',o=>o.finance?.educationRoutes?.routes?.join('; ')||'Not mapped in reviewed data'],['Wages: percentiles, geography and date',o=>o.finance?.earnings?`${o.finance.earnings.p25!=null?`P25 $${Math.round(o.finance.earnings.p25).toLocaleString()}; `:''}${o.finance.earnings.median!=null?`median $${Math.round(o.finance.earnings.median).toLocaleString()}; `:''}${o.finance.earnings.p75!=null?`P75 $${Math.round(o.finance.earnings.p75).toLocaleString()}; `:''}${o.finance.earnings.geography||'geography unavailable'}; ${o.finance.earnings.referencePeriod||'date unavailable'}; ${o.finance.earnings.population||'population unavailable'}`:'Not available in reviewed data'],['Outlook',o=>o.finance?.outlook?.period?`${o.finance.outlook.period}: ${o.finance.outlook.value||'not available'}`:'Not available in reviewed data; confirm current projections for your location in the official occupation profile'],['Unanswered questions',o=>o.settings.length?'What schedule, teamwork, and demands vary by employer?':'What setting, schedule, teamwork, and demands should I ask about for this role?'],['Your saved question',o=>state.exploration?.careerQuestions?.[o.id]||'No reflection question saved yet'],['Experiment',o=>o.experiment.detail]];return `<div class="page-intro catalog-intro"><div><span class="eyebrow">COMPARE OCCUPATIONS</span><h1>Compare the work itself.</h1><p class="intro-copy">Differences are questions to investigate, not a score or a winner.</p></div><a class="button secondary" href="#/catalog">Add or change careers ↗</a></div><div class="compare-head"><h2>Selected careers</h2><div class="comparison-cells">${items.map(o=>`<article><h3><a href="#/career/${h(o.id)}">${h(o.title)}</a></h3><button class="text-link" data-action="career-compare" data-id="${h(o.id)}">Remove from comparison</button></article>`).join('')}</div></div><div class="career-comparison">${rows.map(([label,value])=>`<section class="comparison-row"><h2>${h(label)}</h2><div class="comparison-cells">${items.map(o=>`<article><h3><a href="#/career/${h(o.id)}">${h(o.title)}</a></h3><p>${h(value(o))}</p>${compareSources(o,label)}${label==='Outlook'?`<a class="comparison-source" href="${h(o.url)}" target="_blank" rel="noopener">Official occupation profile for outlook context ↗</a>`:''}${label==='Unanswered questions'||label==='Your saved question'?`<a class="text-link" href="#/career-reflection/${h(o.id)}">Save this question for reflection →</a>`:''}</article>`).join('')}</div></section>`).join('')}</div><p class="occupation-attribution">No overall rating is calculated. Missing information stays visible as “Not available.”</p>`;}
